// ── T5 ENDING ────────────────────────────────────────────────────────────────
export function getT5Ending(score) {
  const max = 100 + 40 * 15; // 700
  const pct = score / max;
  if (pct >= 0.85) return {
    title: 'Studio Veteran',
    summary: 'You navigated the messy, political, human side of design with sophistication. Clients, developers, critique, handoff — you handled them all with empathy, evidence, and principle. You\'re the designer everyone wants on their team.',
  };
  if (pct >= 0.65) return {
    title: 'Seasoned Practitioner',
    summary: 'You have solid professional instincts. You communicate well, handle critique with maturity, and collaborate effectively. A few more reps on the harder situations — scope creep, upward critique, leadership moments — will round out your studio practice.',
  };
  if (pct >= 0.45) return {
    title: 'Developing Professional',
    summary: 'The technical skills are there. The professional skills are still being built. You sometimes defaulted to avoidance when a harder conversation would have produced a better outcome. The good news: these skills improve faster than visual design skills — they just require intention.',
  };
  return {
    title: 'Studio Fundamentals Needed',
    summary: 'Professional design practice is as much about people as it is about pixels. The studio skills — client management, developer collaboration, critique, career navigation — are learnable. This track showed you where the gaps are. That\'s the first step.',
  };
}
